head.script:
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "scwin.checkLabel()","true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};
scwin.checkLabel = function () {
    var dataCheckboxLabel = WebSquare.util.getDataPrefix("checkboxLabel");
    if (WebSquare.wUnit.getDomById($p.id+'grid1_column7').textContent == WebSquare.wUnit.getDomById($p.id+'grid1_column7').getAttribute(dataCheckboxLabel)) {
        return true;
    }
    return false;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setData(["가", 5, "서울", 12,
        "나", 4, "인천", 34,
        "다", 8, "대구", 64,
        "라", 1, "부산", 23
    ]);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
};
